/**
 * Hand-curated supplements to `assets/language-registry.json`, the snapshot of VS Code's built-in language
 * contributions generated by `scripts/update-language-registry.ts`.
 *
 * The upstream `vscode-icons` manifest keys most source files by VS Code language id (`languageIcons`), and a real
 * VS Code install resolves a file to that id through its language registry. The generated snapshot covers every
 * language VS Code ships; these tables only add what it cannot know:
 *
 * - languages contributed by third-party extensions that vscode-icons has an icon for (`astro`, `vue`, `toml`, ...);
 * - deliberate overrides where vscode-icons has a more specific icon than VS Code's default association
 *   (`*.editorconfig` as `editorconfig` rather than `properties`).
 *
 * A supplement entry wins over the generated registry. `src/__tests__/index.test.ts` verifies every target language
 * id against `assets/manifest.json` and rejects entries that change nothing (shadowed by the manifest's own exact
 * name or extension keys, or resolving to the same icon as the generated registry), so this file never drifts back
 * into a copy of either.
 */

/** Lowercased exact file names to a language id. */
export const FILENAME_LANGUAGE_BRIDGE: Readonly<Record<string, string>> = {
    'cmakelists.txt': 'cmake',
    'justfile': 'just',
};

